  <script>
    const statusRegion = document.getElementById("page-status");
    const addToBagButtons = document.querySelectorAll(".card-action");
    const filterButtons = document.querySelectorAll(".filter-chip");
    const editorialCards = document.querySelectorAll(".editorial-card");
    const editorialStatus = document.getElementById("editorial-status");

    addToBagButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const productName = button.dataset.productName;

        if (!productName) {
          return;
        }

        statusRegion.textContent = productName + " added to your bag.";
      });
    });

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const filter = button.dataset.filter;

        if (!filter) {
          return;
        }

        filterButtons.forEach((chip) => {
          chip.setAttribute("aria-pressed", String(chip === button));
        });

        let visibleCount = 0;

        editorialCards.forEach((card) => {
          const matches = filter === "all" || card.dataset.category === filter;
          card.hidden = !matches;

          if (matches) {
            visibleCount += 1;
          }
        });

        editorialStatus.textContent = filter === "all"
          ? "Showing all " + visibleCount + " stories."
          : "Showing " + visibleCount + " " + filter + " " + (visibleCount === 1 ? "story." : "stories.");
      });
    });
  </script>
